// Constant-time compare: the verify token is the only thing standing
// between this public URL and anyone subscribing their own Meta app to it.
const crypto = require('crypto');
const q = $input.first().json.query || {};
const expected = String($env.META_VERIFY_TOKEN_PROPEL || '');
const got = String(q['hub.verify_token'] || '');
const ok = expected.length > 0 && got.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
if (q['hub.mode'] === 'subscribe' && ok) {
  return [{ json: { status: 200, body: String(q['hub.challenge'] || '') } }];
}
return [{ json: { status: 403, body: 'Forbidden' } }];

// Meta signs every POST with an HMAC over the RAW bytes. Without this check
// anyone who learns the URL can post fabricated buyer messages straight into
// the attribution ledger our commission claims rest on.
const crypto = require('crypto');
const item = $input.first();
const secret = String($env.PROPEL_APP_SECRET || '');
const header = String(item.json.headers?.['x-hub-signature-256'] || '');
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64') : Buffer.from(JSON.stringify(item.json.body || {}));
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const ok = secret && header.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(header), Buffer.from(expected));
return [{ json: { ok, body: item.json.body, status: ok ? 200 : 403 } }];

/**
 * Channel normaliser — the single source of truth.
 *
 * Every inbound channel collapses to ONE envelope shape so the brain,
 * the ledger and the dispatcher never learn what a channel is. Adding a
 * channel means adding a case here; it means changing nothing downstream.
 *
 * This file is unit-tested (tools/test-normalizer.js) and its source is
 * embedded verbatim into the workflow JSON at build time, so what ships
 * is exactly what was tested.
 */


const crypto = require('crypto');

const sha256 = s => crypto.createHash('sha256').update(String(s)).digest('hex');

/** Envelope: the only shape anything downstream ever sees. */
function envelope(o) {
  return {
    client_id:           o.client_id || '',
    channel:             o.channel,            // whatsapp | instagram_dm | instagram_comment | email
    provider_message_id: o.provider_message_id || '',
    contact_id:          o.contact_id || '',   // channel-native id, used for replying
    contact_e164:        o.contact_e164 || '',
    contact_email:       o.contact_email || '',
    contact_handle:      o.contact_handle || '',
    contact_hash:        o.contact_hash || sha256(o.contact_id || o.contact_e164 || o.contact_email || ''),
    display_name:        o.display_name || '',
    text:                (o.text || '').trim(),
    media_type:          o.media_type || 'text',
    occurred_at:         o.occurred_at || new Date().toISOString(),
    thread_ref:          o.thread_ref || '',   // what a reply must quote (IG comment id, email Message-ID)
    subject:             o.subject || '',
    is_actionable:       o.is_actionable !== false,
    skip_reason:         o.skip_reason || ''
  };
}

const skip = (channel, reason) => envelope({ channel, is_actionable: false, skip_reason: reason });

/** WhatsApp Cloud API webhook body. */
function fromWhatsApp(body, client_id) {
  const value = body?.entry?.[0]?.changes?.[0]?.value;
  if (value?.statuses) return skip('whatsapp', 'status_callback');
  const m = value?.messages?.[0];
  if (!m) return skip('whatsapp', 'no_message');

  const contact = value?.contacts?.[0];
  const type = m.type || 'text';
  let text = '';
  if (type === 'text')                      text = m.text?.body || '';
  else if (type === 'button')               text = m.button?.text || '';
  else if (type === 'interactive')          text = m.interactive?.button_reply?.title || m.interactive?.list_reply?.title || '';
  else if (['image','video','document'].includes(type)) text = m[type]?.caption || '';

  return envelope({
    client_id, channel: 'whatsapp',
    provider_message_id: m.id,
    contact_id: m.from, contact_e164: m.from,
    display_name: contact?.profile?.name || '',
    text, media_type: type,
    occurred_at: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : new Date().toISOString()
  });
}

/** Instagram messaging + comment webhooks. */
function fromInstagram(body, client_id) {
  const entry = body?.entry?.[0];

  // Comment on a post/reel
  const change = entry?.changes?.[0];
  if (change?.field === 'comments') {
    const v = change.value || {};
    // Never reply to the business replying to itself.
    if (v.from?.id && entry?.id && v.from.id === entry.id) return skip('instagram_comment', 'own_comment');
    return envelope({
      client_id, channel: 'instagram_comment',
      provider_message_id: v.id,
      contact_id: v.from?.id, contact_handle: v.from?.username || '',
      display_name: v.from?.username || '',
      text: v.text || '',
      thread_ref: v.id,          // one private reply is allowed against this comment id
      occurred_at: new Date().toISOString()
    });
  }

  // Direct message
  const msg = entry?.messaging?.[0];
  if (msg) {
    if (msg.message?.is_echo) return skip('instagram_dm', 'echo');
    if (msg.read || msg.delivery) return skip('instagram_dm', 'read_or_delivery_receipt');
    return envelope({
      client_id, channel: 'instagram_dm',
      provider_message_id: msg.message?.mid,
      contact_id: msg.sender?.id,
      text: msg.message?.text || '',
      media_type: msg.message?.attachments?.[0]?.type || 'text',
      occurred_at: msg.timestamp ? new Date(Number(msg.timestamp)).toISOString() : new Date().toISOString()
    });
  }
  return skip('instagram_dm', 'unrecognised_payload');
}

/** IMAP Email Trigger output. */
function fromEmail(mail, client_id) {
  const from = mail?.from?.value?.[0] || {};
  const address = (from.address || mail?.from?.text || '').toLowerCase();

  // Never answer machines. An auto-reply loop between two robots is
  // the classic way an email bot embarrasses a client.
  const headers = mail?.headers || {};
  const h = k => String(headers[k] ?? headers[k?.toLowerCase()] ?? '');
  if (h('auto-submitted') && !/^no$/i.test(h('auto-submitted'))) return skip('email', 'auto_submitted');
  if (h('x-autoreply') || h('x-autorespond') || h('precedence').match(/bulk|junk|list/i)) return skip('email', 'auto_responder');
  if (h('list-unsubscribe')) return skip('email', 'bulk_mail');
  if (/^(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounce)/i.test(address)) return skip('email', 'noreply_sender');

  const subject = mail?.subject || '';
  if (/^(out of office|automatic reply|auto:|undeliverable)/i.test(subject)) return skip('email', 'out_of_office');

  // Strip quoted history so the model reads the new message, not the whole thread.
  const raw = mail?.textPlain || mail?.text || '';
  const text = String(raw)
    .split(/^\s*(On .+ wrote:|-{2,}\s*Original Message|_{5,}|From:\s)/m)[0]
    .split(/\n>{1,}/)[0]
    .trim();

  return envelope({
    client_id, channel: 'email',
    provider_message_id: mail?.messageId || '',
    contact_id: address, contact_email: address,
    display_name: from.name || '',
    text, subject,
    thread_ref: mail?.messageId || '',
    occurred_at: mail?.date ? new Date(mail.date).toISOString() : new Date().toISOString()
  });
}

function normalize(channel, payload, client_id) {
  switch (channel) {
    case 'whatsapp':  return fromWhatsApp(payload, client_id);
    case 'instagram': return fromInstagram(payload, client_id);
    case 'email':     return fromEmail(payload, client_id);
    default:          return skip(channel || 'unknown', 'unsupported_channel');
  }
}


const payload = $input.first().json;
if (!payload.ok) return [{ json: envelope({ channel: 'instagram_dm', is_actionable: false, skip_reason: 'bad_signature' }) }];
return [{ json: normalize('instagram', payload.body, "propel") }];

// Front-door dedup. Meta redelivers webhooks, and a redelivery is the same
// message, not a new one. This sits BEFORE the keyword lane because most
// messages never reach the CORE -- a dedup that lives only in the CORE lets
// a redelivered "price" DM fire the price card twice.
//
// Returning no items ends the branch: no reply, no ledger row, no alert.
const env = $input.first().json;
const key = env.provider_message_id;
if (!key) return [{ json: env }];   // nothing to key on: let it through, never drop a buyer

const store = $getWorkflowStaticData('global');
store.seenMsgs = store.seenMsgs || {};
const now = Date.now(), TTL = 24 * 60 * 60 * 1000;
for (const k of Object.keys(store.seenMsgs)) if (now - store.seenMsgs[k] > TTL) delete store.seenMsgs[k];

if (store.seenMsgs[key]) return [];
store.seenMsgs[key] = now;
return [{ json: env }];

/**
 * Keyword fast lane.
 *
 * A deterministic layer that sits IN FRONT of the Concierge brain. An exact
 * rule match returns a pre-written, human-approved response with no model
 * call: ~0ms, ₦0, and zero hallucination surface. Anything that does not
 * match falls through to the brain, which still has the KB and the
 * guardrails.
 *
 * Same doctrine as docs/13 "arithmetic never goes to a language model":
 * an answer we already know the exact words for should never be regenerated.
 *
 * Two invariants this file exists to hold:
 *   1. An escalate_only rule BEATS any commercial rule when both match, so
 *      "what is the ROI on the 4 bedroom" can never fire the price card.
 *   2. A rule whose link cannot be resolved ships with no link at all.
 *      A keyword automation that DMs a dead link is worse than none.
 *
 * Unit-tested (tools/test-keywords.js) and embedded verbatim into the
 * workflow JSON at build time, so shipped code is tested code.
 */


/** Spelled numbers and shorthand people actually type in Lagos IG comments. */
const WORD_NUMBERS = {
  one: '1', two: '2', three: '3', four: '4', five: '5', six: '6',
  seven: '7', eight: '8', nine: '9', ten: '10'
};

/**
 * Fold a raw message into comparable tokens.
 * Strips emoji and punctuation (IG comments are ~40% emoji), normalises
 * "4bed" / "4-bedroom" / "four bedroom" to one shape, and lowercases.
 */
function normalizeText(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[‘’ʼ]/g, "'")
    .replace(/[^\p{L}\p{N}\s']/gu, ' ')       // emoji, ₦, punctuation -> space
    .replace(/'/g, '')                        // don't -> dont, governor's -> governors
    .replace(/(\d)\s*(bedrooms?|beds?|bdrm|br)\b/g, '$1 bedroom')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(s) {
  return normalizeText(s)
    .split(' ')
    .filter(Boolean)
    .map(t => WORD_NUMBERS[t] || t);
}

/**
 * Contiguous token-subsequence match.
 *
 * Token-based on purpose: a naive substring search matches "land" inside
 * "Ireland" and "landscape", which is the single most common way a keyword
 * bot embarrasses a client in public.
 */
function containsPhrase(hay, needle) {
  if (!needle.length || needle.length > hay.length) return false;
  outer:
  for (let i = 0; i <= hay.length - needle.length; i++) {
    for (let j = 0; j < needle.length; j++) {
      if (hay[i + j] !== needle[j]) continue outer;
    }
    return true;
  }
  return false;
}

/** Pre-tokenise a rule's phrases once, at compile time. */
function compileRule(rule) {
  return {
    ...rule,
    _phrases: (rule.trigger_phrases || []).map(p => ({ raw: p, tokens: tokenize(p) }))
                                          .filter(p => p.tokens.length > 0)
  };
}

function compile(rules) {
  return rules.map(compileRule);
}

/**
 * Score a rule against a tokenised message.
 * Longer matched phrases win — "2 bedroom price" resolves to the 2-bedroom
 * card, not the generic price card.
 */
function scoreRule(rule, hay) {
  let best = null;
  for (const p of rule._phrases || []) {
    if (!containsPhrase(hay, p.tokens)) continue;
    if (!best || p.tokens.length > best.tokens.length) best = p;
  }
  if (!best) return null;
  return { phrase: best.raw, score: best.tokens.length * 100 - (rule.priority || 50) };
}

/** Deterministic ordering so the same message always resolves the same way. */
function pickBest(hits) {
  return hits.sort((a, b) =>
    b.score - a.score ||
    (a.rule.priority || 50) - (b.rule.priority || 50) ||
    String(a.rule.rule_id).localeCompare(String(b.rule.rule_id))
  )[0];
}

/**
 * Resolve a rule's outbound link from client config.
 * Returns '' when the link cannot be built — never a half-formed URL.
 */
function resolveLink(rule, links) {
  const cfg = links || {};
  if (!rule.link_kind || rule.link_kind === 'none') return '';
  if (rule.link_kind === 'website') return cfg.website || '';
  if (rule.link_kind === 'whatsapp') {
    if (cfg.mode !== 'concierge' && cfg.mode !== 'human_line') return '';
    if (!cfg.wa_e164 || !cfg.whatsapp_template) return '';
    return cfg.whatsapp_template
      .replace('{{WA_E164}}', String(cfg.wa_e164))
      .replace('{{CODE}}', encodeURIComponent(rule.link_code || rule.rule_id));
  }
  return '';
}

/**
 * Is this rule's promotional text in force right now?
 *
 * A promotion is time-bound by definition. The failure mode we are designing
 * out is an automation still quoting a N5,000,000 entry deposit in November
 * for an offer that ended in September -- and a buyer turning up with the
 * wrong money because a robot never got the memo. A promo with no end date
 * cannot be compiled (tools/build-keywords.js enforces it), and an expired
 * one falls back to the standard warranted terms on its own.
 */
function isPromoLive(rule, now) {
  if (!rule.promo_response) return false;

  if (rule.promo_from) {
    const start = Date.parse(rule.promo_from + 'T00:00:00Z');
    if (Number.isFinite(start) && now < start) return false;
  }

  // A campaign that runs "until we sell out" has no end date, and pretending
  // otherwise would be inventing a fact. What it must have instead is a
  // REVIEW date: someone re-confirms it is still running, or the assistant
  // quietly goes back to the signed standard terms. Same safety property,
  // fitted to how the client actually sells.
  if (rule.promo_until) {
    const end = Date.parse(rule.promo_until + 'T23:59:59Z');
    if (!Number.isFinite(end) || now > end) return false;
  } else if (rule.promo_review_by) {
    const due = Date.parse(rule.promo_review_by + 'T23:59:59Z');
    if (!Number.isFinite(due) || now > due) return false;
  } else {
    return false;   // neither an end nor a review date: fail safe
  }
  return true;
}

/**
 * Build the outbound message body for a matched rule.
 * When no link resolves, the call to action degrades to "reply here" rather
 * than pointing a buyer at nothing.
 */
function buildBody(rule, cfg, bodyText) {
  // Every card is lint-guaranteed to close on a question, so an unresolved
  // link needs no apology bolted on the end -- the question already invites
  // the reply. Silence beats "reply here and the team will pick it up".
  const link = resolveLink(rule, cfg && cfg.links);
  const parts = [bodyText || rule.dm_response];
  if (link) parts.push(link);
  if (cfg && cfg.assistant_signature) parts.push(cfg.assistant_signature);
  return parts.join('\n\n');
}

/**
 * Match a message against the compiled rule set.
 *
 * @returns {object} always an object; `matched:false` means "hand to the brain".
 */
function match(rules, text, cfg) {
  const hay = tokenize(text);
  if (!hay.length) return { matched: false, reason: 'empty_text' };

  const escalations = [];
  const fast = [];

  for (const rule of rules) {
    if (rule.status !== 'live') continue;
    const hit = scoreRule(rule, hay);
    if (!hit) continue;
    (rule.class === 'escalate_only' ? escalations : fast).push({ rule, ...hit });
  }

  // Invariant 1: safety class outranks commercial class, always. A buyer
  // asking about returns on a specific unit gets a human, not a price card.
  const winner = escalations.length ? pickBest(escalations) : (fast.length ? pickBest(fast) : null);
  if (!winner) return { matched: false, reason: 'no_rule_matched' };

  const r = winner.rule;
  const now = (cfg && cfg.now) || Date.now();
  const promoLive = isPromoLive(r, now);
  return {
    matched: true,
    rule_id: r.rule_id,
    intent: r.intent,
    rule_class: r.class,
    matched_phrase: winner.phrase,
    score: winner.score,
    promo_active: promoLive,
    promo_until: promoLive ? r.promo_until : '',
    reply: buildBody(r, cfg, promoLive ? r.promo_response : r.dm_response),
    public_comment_reply: r.public_comment_reply || '',
    link: resolveLink(r, cfg && cfg.links),
    link_code: r.link_code || r.rule_id,
    escalate: r.escalate === true,
    escalation_reason: r.escalate === true ? ('keyword rule ' + r.rule_id + ': ' + r.intent) : '',
    grounded_in: r.grounded_in || [],
    unit_interest: r.unit_id || ''
  };
}



// The keyword table, compiled from (no keyword table: every message goes to the brain).
// Rebuild with: node tools/build-keywords.js && node tools/build-workflows.js
const TABLE = {"rules":[]};
const CFG = {"assistant_signature":"","links":{"mode":"none"}};
const RULES = compile(TABLE.rules);

const env = $input.first().json;
const hit = match(RULES, env.text, CFG);

if (!hit.matched) {
  // No rule owns this question. The brain gets it, with the KB and the
  // guardrails — a miss is a fall-through, never a dead end.
  return [{ json: { ...env, lane: 'brain', keyword_miss_reason: hit.reason } }];
}

// Shaped exactly like a model response so it flows through the SAME
// guardrail node the brain's output does. A human edit to the sheet gets
// policed at runtime, not only at build time.
return [{ json: { ...env, lane: 'keyword', rule_id: hit.rule_id, intent: hit.intent, matched_phrase: hit.matched_phrase,
  public_comment_reply: hit.public_comment_reply, link_code: hit.link_code,
  text: JSON.stringify({ reply: hit.reply, escalate: hit.escalate, escalation_reason: hit.escalation_reason,
                         unit_interest: hit.unit_interest, grounded_in: hit.grounded_in }) } }];

// Post-generation guardrails. The model is not trusted to police itself.
const raw = $input.first().json;
const text = raw?.content?.parts?.[0]?.text
          ?? raw?.candidates?.[0]?.content?.parts?.[0]?.text
          ?? raw?.text ?? '';

const ESCALATION_LINE = "Let me get you the exact figure from the team — one moment. I'm connecting you with someone now.";

let out;
try {
  out = JSON.parse(String(text).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim());
} catch (e) {
  // Unparseable output is a failure, not a message to forward.
  return [{ json: { reply: ESCALATION_LINE, escalate: true, escalation_reason: 'model returned unparseable output', unit_interest: '', grounded_in: [], guard_triggered: 'parse_error' } }];
}

let reply    = String(out.reply || '');
let escalate = out.escalate === true;
let reason   = String(out.escalation_reason || '');
const grounded = Array.isArray(out.grounded_in) ? out.grounded_in : [];
let guard = '';

// 1. Banned-topic sweep. Catches a model that complied in tone but not substance.
const BANNED = [
  // 'appreciat' needs care: "I appreciate your question" is normal Nigerian
  // business English. Match the investment senses only.
  { re: /\b(roi|rental yield|yields?|return on investment|resale value|capital growth)\b|\bappreciation\b|\b(will|would|should|can|could|may|might)\s+appreciate\b|\bappreciate[sd]?\s+in\s+value\b/i, why: 'investment projection' },
  { re: /\b(guarantee|guaranteed|assured returns?)\b/i, why: 'guarantee language' },
  { re: /\baccount (number|details)\b|\b\d{10}\b/i, why: 'possible account number' },
  { re: /\bonly \d+ (unit|plot|left)/i, why: 'scarcity claim' }
];
for (const b of BANNED) {
  if (b.re.test(reply)) { escalate = true; guard = b.why; reply = ESCALATION_LINE; reason = reason || b.why; break; }
}

// 2. Ungrounded factual claim: money or measurements with nothing cited.
// Curly apostrophes are what models actually emit -- match both forms.
const looksFactual = /₦|\bN\d|\bnaira\b|\bsqm\b|\bbedroom\b|\bc of o\b|governor[\u2019']?s consent|\bgovernor'?s consent\b/i.test(reply);
if (!guard && looksFactual && grounded.length === 0) {
  escalate = true; guard = 'ungrounded_factual_claim'; reply = ESCALATION_LINE;
  reason = reason || 'stated a fact without citing the knowledge base';
}

// 3. Never return an empty reply.
if (!reply.trim()) { reply = ESCALATION_LINE; escalate = true; guard = guard || 'empty_reply'; }

return [{ json: { reply, escalate, escalation_reason: reason, unit_interest: String(out.unit_interest || ''), grounded_in: grounded, guard_triggered: guard } }];

// Meta's two hard limits, enforced before we spend them:
//   1. ONE private reply per comment, inside a 7-day window
//   2. ~200 automated DMs an hour
// Overflow is queued to a human, never dropped. A buyer who gets no answer
// is a lost lead; a buyer who gets a late human answer is still a lead.
const LIMITS = {"public_reply_enabled":true,"private_replies_per_comment":1,"private_reply_window_days":7,"max_automated_dms_per_hour":180};
const item = $input.first().json;
if (!item.send) return [{ json: { ...item, send: false, reason: item.reason || 'empty_reply' } }];

const store = $getWorkflowStaticData('global');
store.repliedComments = store.repliedComments || {};
store.hourly = store.hourly || { windowStart: 0, count: 0 };

const now = Date.now();
const WINDOW = LIMITS.private_reply_window_days * 24 * 60 * 60 * 1000;
for (const k of Object.keys(store.repliedComments)) {
  if (now - store.repliedComments[k] > WINDOW) delete store.repliedComments[k];
}

if (item.comment_id) {
  if (store.repliedComments[item.comment_id]) {
    return [{ json: { ...item, send: false, reason: 'private_reply_already_used_for_this_comment' } }];
  }
  store.repliedComments[item.comment_id] = now;
}

if (now - store.hourly.windowStart > 60 * 60 * 1000) store.hourly = { windowStart: now, count: 0 };
if (store.hourly.count >= LIMITS.max_automated_dms_per_hour) {
  return [{ json: { ...item, send: false, reason: 'hourly_cap_reached', escalate: true,
                    escalation_reason: 'automation hourly cap reached — needs a human' } }];
}
store.hourly.count++;

return [{ json: { ...item, send: true } }];

// Nothing sent: cap reached, reply already used, or an empty reply.
// This is the escalation queue until the notifier workflow ships.
return [{ json: { held: true, reason: $json.reason, rule_id: $json.rule_id, handle: $json.contact_handle, channel: $json.channel } }];
